      "proposed_laureates": [
        "Heino Falcke",
        "Sheperd S. Doeleman",
        "J. Anton Zensus"
      ],
      "assessment": {
        "nobel_worthiness": "Black-hole shadow imaging is an exceptional technical and observational achievement with fundamental physical reach.",
        "attribution": "Falcke articulated the shadow-imaging opportunity, Doeleman led its realization, and Zensus represents key very-long-baseline interferometry leadership.",
        "maturity": "Images of two black holes and extensive validation work establish the technique beyond a one-off result.",
        "uncertainties": [
          "Attribution within the Event Horizon Telescope collaboration is unusually broad.",
          "The interpretation remains dependent on detailed source modeling."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have produced a major advance in timekeeping and precision tests, with far-reaching scientific uses.",
        "attribution": "Katori introduced the magic-wavelength lattice-clock concept and Ye made foundational experimental advances.",
        "maturity": "Independent laboratories now achieve extraordinary reproducibility and performance.",
        "uncertainties": [
          "The eventual practical redefinition of the second is still a collective metrological process."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Erik H. M. Heijne",
        "Michael Campbell",
        "Sherwood I. Parker"
      ],
      "assessment": {
        "nobel_worthiness": "Silicon microstrip and pixel detectors are enabling measurement technologies that reshaped particle physics and spread widely beyond it.",
        "attribution": "The named scientists represent crucial detector concepts and their translation into usable high-resolution systems.",
        "maturity": "Their impact is long established across major experiments and applications.",
        "uncertainties": [
          "The technological lineage spans many laboratories and may be difficult to delimit cleanly."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Andrew G. Lyne",
        "Marta Burgay",
        "Michael Kramer"
      ],
      "assessment": {
        "nobel_worthiness": "The double pulsar provides an unusually clean strong-field laboratory for testing gravity and relativistic astrophysics.",
        "attribution": "Burgay and Lyne are central to discovery, and Kramer to the ensuing precision timing and physical tests.",
        "maturity": "A long timing baseline has made the system a durable and increasingly precise test bed.",
        "uncertainties": [
          "Its scientific impact overlaps conceptually with earlier prize-recognized tests of general relativity."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B015",
